<template>
  <header class="sn" :class="dark ? 'sn-dark' : 'sn-light'">
    <div class="sn-inner">
      <router-link :to="homePath" class="sn-brand">
        <span class="sn-brand-mark">EJ</span>
        <span class="sn-brand-name">EJSOFT</span>
      </router-link>

      <nav class="sn-nav">
        <router-link :to="homePath" class="sn-link" exact-active-class="active">
          {{ t.home }}
        </router-link>

        <div class="sn-products" v-click-outside="closeMenu">
          <button
            type="button"
            class="sn-link sn-products-btn"
            :class="{ active: menuOpen || isProductRoute }"
            :aria-expanded="menuOpen ? 'true' : 'false'"
            @click="menuOpen = !menuOpen"
          >
            {{ t.products }}
            <span class="sn-caret" :class="{ up: menuOpen }">▾</span>
          </button>

          <transition name="sn-fade">
            <div v-if="menuOpen" class="sn-layer" role="menu">
              <router-link
                :to="familyLinePath"
                class="sn-layer-item"
                role="menuitem"
                @click.native="closeMenu"
              >
                <span class="sn-layer-icons">
                  <img :src="icons.familyLine" :alt="t.familyLine" class="sn-layer-icon" />
                </span>
                <span>
                  <span class="sn-layer-title">{{ t.familyLine }}</span>
                  <span class="sn-layer-sub">{{ t.familyLineSub }}</span>
                </span>
              </router-link>
              <router-link
                :to="newsFilterPath"
                class="sn-layer-item"
                role="menuitem"
                @click.native="closeMenu"
              >
                <span class="sn-layer-icons">
                  <img :src="icons.newsFilter" :alt="t.newsFilter" class="sn-layer-icon" />
                </span>
                <span>
                  <span class="sn-layer-title">{{ t.newsFilter }}</span>
                  <span class="sn-layer-sub">{{ t.newsFilterSub }}</span>
                </span>
              </router-link>
            </div>
          </transition>
        </div>

        <!-- 제품 옆: 언어 전환 + 다크/라이트 토글 -->
        <div class="sn-controls">
          <div class="sn-lang">
            <router-link :to="langPaths.ko" class="sn-lang-btn" :class="{ active: lang === 'ko' }">한국어</router-link>
            <router-link :to="langPaths.en" class="sn-lang-btn" :class="{ active: lang === 'en' }">EN</router-link>
          </div>
          <button
            type="button"
            class="sn-theme-btn"
            :aria-label="t.toggleTheme"
            @click="toggleTheme"
          >{{ dark ? '☀' : '☾' }}</button>
        </div>
      </nav>
    </div>
  </header>
</template>

<script>
const TEXT = {
  ko: {
    home: '홈',
    products: '제품',
    familyLine: '패밀리 라인',
    familyLineSub: '우리 가족의 모든 순간',
    newsFilter: '뉴스 필터',
    newsFilterSub: '보고 싶은 뉴스만, 깔끔하게',
    toggleTheme: '밝기 전환'
  },
  en: {
    home: 'Home',
    products: 'Products',
    familyLine: 'Family Line',
    familyLineSub: 'Every family moment',
    newsFilter: 'News Filter',
    newsFilterSub: 'Only the news you want',
    toggleTheme: 'Toggle theme'
  }
}

export default {
  name: 'SiteNav',
  directives: {
    // 메뉴 바깥 클릭 시 닫기
    'click-outside': {
      bind (el, binding) {
        el.__snOutside = (e) => {
          if (!(el === e.target || el.contains(e.target))) binding.value(e)
        }
        document.addEventListener('click', el.__snOutside)
      },
      unbind (el) {
        document.removeEventListener('click', el.__snOutside)
      }
    }
  },
  props: {
    lang: { type: String, default: 'ko' }
  },
  data () {
    return { menuOpen: false }
  },
  computed: {
    dark () {
      return this.$store.getters.isDark
    },
    t () {
      return TEXT[this.lang] || TEXT.ko
    },
    icons () {
      const base = process.env.BASE_URL || '/'
      return {
        familyLine: base + 'familyline/app_icon.png',
        newsFilter: base + 'newsfilter/newsfilter_icon.png'
      }
    },
    isEn () {
      return this.lang === 'en'
    },
    homePath () {
      return this.isEn ? '/en' : '/'
    },
    familyLinePath () {
      return this.isEn ? '/familyline/en' : '/familyline'
    },
    newsFilterPath () {
      return this.isEn ? '/newsfilter/en' : '/newsfilter'
    },
    isProductRoute () {
      return /^\/(familyline|newsfilter)/.test(this.$route.path)
    },
    // 현재 페이지의 한국어/영어 경로 (언어 전환 버튼용)
    langPaths () {
      const p = this.$route.path
      if (/^\/familyline/.test(p)) return { ko: '/familyline', en: '/familyline/en' }
      if (/^\/newsfilter/.test(p)) return { ko: '/newsfilter', en: '/newsfilter/en' }
      return { ko: '/', en: '/en' }
    }
  },
  watch: {
    // 라우트가 바뀌면 레이어를 닫는다.
    $route () {
      this.menuOpen = false
    }
  },
  methods: {
    closeMenu () {
      this.menuOpen = false
    },
    toggleTheme () {
      this.$store.commit('toggleTheme')
    }
  }
}
</script>

